package bowling

import "errors"

// Game keeps track of the state of a bowling game.
type Game struct {
	rolls       []int
	frame       int  // current frame index, 0-9
	rollInFrame int  // number of rolls taken in the current frame
	pinsDown    int  // pins knocked down in the current frame since the last lane reset
	over        bool // true once all ten frames are complete
}

var (
	errNegativeRoll   = errors.New("negative roll is invalid")
	errTooManyPins    = errors.New("pin count exceeds pins on the lane")
	errGameOver       = errors.New("cannot roll after game is over")
	errIncompleteGame = errors.New("score cannot be taken until the end of the game")
)

// NewGame returns a new, empty Game.
func NewGame() *Game {
	return &Game{}
}

// Roll records a single throw that knocked down `pins` pins.
// It returns an error if the roll is illegal (negative, too many pins, or
// made after the game has already ended).
func (g *Game) Roll(pins int) error {
	if g.over {
		return errGameOver
	}
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errTooManyPins
	}
	if pins > 10-g.pinsDown {
		return errTooManyPins
	}

	g.rolls = append(g.rolls, pins)
	g.pinsDown += pins
	g.rollInFrame++

	wasStrike := pins == 10
	if g.pinsDown == 10 {
		// All ten pins are down (strike or spare): reset the lane.
		g.pinsDown = 0
	}

	if g.frame < 9 {
		// Frames 1-9 end after a strike or after two rolls.
		if wasStrike || g.rollInFrame == 2 {
			g.frame++
			g.rollInFrame = 0
			g.pinsDown = 0
		}
	} else {
		// The tenth frame: a strike or spare earns one or two fill balls.
		switch g.rollInFrame {
		case 2:
			first := g.rolls[len(g.rolls)-2]
			second := g.rolls[len(g.rolls)-1]
			if first != 10 && first+second != 10 {
				g.over = true // open frame: game over
			}
		case 3:
			g.over = true // fill balls complete: game over
		}
	}
	return nil
}

// Score returns the total score of a completed game.
// It returns an error if the game has not finished.
func (g *Game) Score() (int, error) {
	if !g.over {
		return 0, errIncompleteGame
	}

	rolls := g.rolls
	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case rolls[i] == 10: // strike: 10 plus the next two rolls
			total += 10 + rolls[i+1] + rolls[i+2]
			i++
		case rolls[i]+rolls[i+1] == 10: // spare: 10 plus the next roll
			total += 10 + rolls[i+2]
			i += 2
		default: // open frame
			total += rolls[i] + rolls[i+1]
			i += 2
		}
	}
	return total, nil
}

